from calc1_helpers import *
x,y=s.symbols('x y',real=True);P=s.pi;R=s.Rational;b=CalcBook('5.4',[398,399,400]);g=R(98,10)
checks=[]
def I(expr,lo,hi,v=x):
 expr=s.sympify(expr);val=s.simplify(s.integrate(expr,(v,lo,hi)));assert not val.has(s.Integral)
 q=mp.quad(s.lambdify(v,expr,'mpmath'),[float(lo),float(hi)]);assert abs(float(val)-float(q))<1e-8*max(1,abs(float(q)));checks.append([str(expr),str(lo),str(hi),str(val)])
 return val,fs(s.latex(s.Integral(expr,(v,lo,hi)))+'='+tex(val))
def add(n,st,steps,ans,check,parts=[]):
 b.add(n,398 if n<=4 else 399 if n<=24 else 400,('일과 에너지','Work and energy'),st,steps,ans,parts=parts);b.verify(n,*check);b.save()
def answer(W,unit='J'):return same(M(r'W='+tex(W)+r'\ \mathrm{'+unit+'}'))
add(1,('질량200 kg을 지면 위1.5 m에서2.0 m까지 들어 올리는 일을 구하라. g=9.8 m/s²를 사용하라.','Find the work to lift200 kg from1.5 m to2.0 m above ground. Use g=9.8 m/s².'),fs(r'F=mg=200(9.8)=1960\ \mathrm N',r'W=F\Delta h=1960(2.0-1.5)=980\ \mathrm J'),answer(980),('중력 위치에너지 변화 mgΔh와 일치한다.','Agrees with the gravitational potential-energy change mgΔh.'))
add(2,('무게1100 lb인 피아노를35 ft 위로 들어 올리는 일을 구하라.','Find the work to hoist an1100-lb piano35 ft upward.'),fs(r'F=1100\ \mathrm{lb},\quad\Delta h=35\ \mathrm{ft}',r'W=1100\cdot35=38500\ \mathrm{ft\!\cdot lb}'),answer(38500,r'ft\cdot lb'),('lb가 이미 힘의 단위이므로 중력가속도를 다시 곱하지 않는다.','Pounds here already measure force, so no further gravity factor is used.'))
for n,eq,expr,lo,hi,unit in[(3,r'F(x)=5x^{-2}\ \mathrm{lb},\quad1\le x\le10\ \mathrm{ft}',5/x**2,1,10,r'ft\cdot lb'),(4,r'F(x)=4\sqrt x\ \mathrm N,\quad4\le x\le16\ \mathrm m',4*s.sqrt(x),4,16,'J')]:
 W,steps=I(expr,lo,hi);add(n,(M(eq)+'힘이 물체를 주어진 구간에서 이동시킬 때 한 일을 구하라.',M(eq)+'Find the work done by this force over the stated interval.'),[('변하는 힘을 이동 거리에 대해 적분한다.','Integrate the variable force with respect to displacement.')]+steps,answer(W,unit),('원시함수를 미분하면 주어진 힘으로 돌아오며 적분을 독립 수치구적으로 대조했다.','The antiderivative differentiates to the given force, and independent quadrature checks the integral.'))
add(5,('힘 그래프는(0,0)에서(4 m,30 N)까지 직선으로 증가한 뒤 x=8 m까지30 N이다. 처음8 m 동안 한 일을 구하라.','The force rises linearly from(0,0) to(4 m,30 N), then stays at30 N through x=8 m. Find work over the first8 m.'),fs(r'W=\text{triangle area}+\text{rectangle area}',r'W=\frac12(4)(30)+(8-4)(30)=180\ \mathrm J'),answer(180),('구간별 적분 ∫₀⁴7.5x dx+∫₄⁸30 dx도180이다.','Piecewise integration ∫₀⁴7.5x dx+∫₄⁸30 dx also gives180.'))
add(6,('x=4,6,8,10,12,14,16,18,20 m에서 힘이5,5.8,7.0,8.8,9.6,8.2,6.7,5.2,4.1 N이다. 중점법으로4–20 m의 일을 추정하라.','At x=4,6,8,10,12,14,16,18,20 m, force values are5,5.8,7.0,8.8,9.6,8.2,6.7,5.2,4.1 N. Estimate work from4 to20 m using midpoints.'),fs(r'\Delta x=4,\quad x_i^*=6,10,14,18',r'W\approx4(5.8+8.8+8.2+5.2)=112\ \mathrm J'),same(M(r'W\approx112\ \mathrm J')),('네 구간이16 m를 덮고 중점 힘 합은28 N이다.','Four intervals cover16 m; the midpoint force sum is28 N.'))
add(7,('용수철을 자연 길이보다4 in 늘려 유지하는 데10 lb가 필요하다. 자연 길이에서6 in 늘리는 일을 구하라.','A spring needs10 lb to hold an extension of4 in. Find the work to stretch it from natural length to6 in extension.'),fs(r'F=kx,\quad k=10/(4/12)=30\ \mathrm{lb/ft}',r'W=\int_0^{1/2}30x\,dx=15(1/2)^2=15/4\ \mathrm{ft\cdot lb}'),answer(R(15,4),r'ft\cdot lb'),('최종 힘15 lb와 이동거리1/2 ft의 삼각형 면적(1/2)·15·(1/2)로 검산했다.','Checked using the force-displacement triangle:(1/2)·15 lb·(1/2 ft).'))
add(8,('자연 길이40 cm인 용수철을10 cm 압축하는 데 유지력60 N이 필요하다. (a)이 압축의 일,(b)길이25 cm까지 압축하는 일을 구하라.','A spring of natural length40 cm needs60 N to hold10 cm compression. Find(a)work for that compression and(b)work to compress it to length25 cm.'),fs(r'k=60/.10=600\ \mathrm{N/m}',r'W(a)=\int_0^a600x\,dx=300a^2',r'W(.10)=3,\quad W(.15)=6.75'),same(M(r'(a)\ 3\ \mathrm J;\qquad(b)\ 6.75\ \mathrm J')),('두 답의 비는 압축량 비(15/10)의 제곱2.25이다.','The work ratio is the squared compression ratio(15/10)²=2.25.'),['a','b'])
add(9,('자연 길이30 cm인 용수철을42 cm까지 늘리는 데2 J가 든다. (a)길이35–40 cm로 늘리는 일,(b)30 N이 만드는 늘어난 길이를 구하라.','A spring of natural length30 cm takes2 J to reach42 cm. Find(a)work from length35 to40 cm and(b)the extension held by30 N.'),fs(r'2=\frac12k(.12)^2\Rightarrow k=2500/9\ \mathrm{N/m}',r'(a)\ W=\frac12\frac{2500}{9}(.10^2-.05^2)=25/24\ \mathrm J',r'(b)\ x=F/k=30/(2500/9)=.108\ \mathrm m'),same(M(r'(a)\ 25/24\ \mathrm J;\qquad(b)\ 10.8\ \mathrm{cm}')),('자연 길이로부터의 변위를 사용했고 원래12 cm 일에k를 대입하면2 J이다.','Used extensions from natural length; substituting k for the original12-cm extension gives2 J.'),['a','b'])
add(10,('자연 길이보다1 ft 늘리는 데12 ft-lb가 드는 용수철을9 in 늘리는 일을 구하라.','A spring takes12 ft-lb to stretch1 ft beyond natural length. Find work for9 in extension.'),fs(r'W(x)=\frac12kx^2,\quad x=9/12=3/4\ \mathrm{ft}',r'W(3/4)=12(3/4)^2=27/4\ \mathrm{ft\cdot lb}'),answer(R(27,4),r'ft\cdot lb'),('k=24 lb/ft를 구해 직접 적분해도27/4이다.','Using k=24 lb/ft and integrating directly also gives27/4.'))
add(11,('자연 길이20 cm인 용수철을20–30 cm로 늘리는 일을W1,30–40 cm로 늘리는 일을W2라 한다. 둘을 비교하라.','For a spring with natural length20 cm, W1 stretches it from20 to30 cm and W2 from30 to40 cm. Compare them.'),fs(r'W_1=\frac12k(.10)^2,\quad W_2=\frac12k(.20^2-.10^2)',r'\frac{W_2}{W_1}=\frac{.04-.01}{.01}=3'),same(M(r'W_2=3W_1')),('같은10 cm라도 두 번째 구간에서는 힘이 더 크며 삼각형 면적 비로도3이다.','Although displacements are equal, force is greater over the second interval; force-graph areas also have ratio3.'))
add(12,('용수철 길이를10–12 cm로 늘리는 데6 J,12–14 cm로 늘리는 데10 J가 든다. 자연 길이를 구하라.','Stretching a spring from10 to12 cm takes6 J;12 to14 cm takes10 J. Find its natural length.'),fs(r'6=\frac{k}{2}[(.12-L)^2-(.10-L)^2]=.02k(.11-L)',r'10=.02k(.13-L)',r'4=.0004k\Rightarrow k=10000\ \mathrm{N/m}',r'6=200(.11-L)\Rightarrow L=.08\ \mathrm m'),same(M(r'L=8\ \mathrm{cm}')),('L=.08,k=10000을 두 일 식에 대입하면 각각6 J와10 J이다.','Substitution of L=.08 and k=10000 returns6 J and10 J in the two work equations.'))
